impl Facing {
    #[must_use]
    pub const fn opposite(&self) -> Self {
        match self {
            Self::North => Self::South,
            Self::South => Self::North,
            Self::East => Self::West,
            Self::West => Self::East,
            Self::Up => Self::Down,
            Self::Down => Self::Up,
        }
    }
}
impl HorizontalFacing {
    #[must_use]
    pub fn all() -> [Self; 4] {
        [Self::North, Self::South, Self::West, Self::East]
    }
    #[must_use]
    pub fn to_offset(&self) -> Vector3<i32> {
        match self {
            Self::North => (0, 0, -1),
            Self::South => (0, 0, 1),
            Self::West => (-1, 0, 0),
            Self::East => (1, 0, 0),
        }
        .into()
    }
    #[must_use]
    pub const fn to_axis(&self) -> HorizontalAxis {
        match self {
            Self::North | Self::South => HorizontalAxis::Z,
            Self::West | Self::East => HorizontalAxis::X,
        }
    }
    #[must_use]
    pub const fn to_facing(&self) -> HorizontalFacing {
        match self {
            Self::North => HorizontalFacing::North,
            Self::South => HorizontalFacing::South,
            Self::West => HorizontalFacing::West,
            Self::East => HorizontalFacing::East,
        }
    }
    #[must_use]
    pub const fn opposite(&self) -> Self {
        match self {
            Self::North => Self::South,
            Self::South => Self::North,
            Self::West => Self::East,
            Self::East => Self::West,
        }
    }
    #[must_use]
    pub const fn rotate_clockwise(&self) -> Self {
        match self {
            Self::North => Self::East,
            Self::South => Self::West,
            Self::West => Self::North,
            Self::East => Self::South,
        }
    }
    #[must_use]
    pub const fn rotate_counter_clockwise(&self) -> Self {
        match self {
            Self::North => Self::West,
            Self::South => Self::East,
            Self::West => Self::South,
            Self::East => Self::North,
        }
    }
}
